import gymnasium as gym
from stable_baselines3 import PPO
from stable_baselines3.common.env_util import make_vec_env
from hrl_wrapper import KaggricultureMacroEnv
import torch

print(f"CUDA available: {torch.cuda.is_available()}")

# Create environment
env = KaggricultureMacroEnv(opponent="random", steps_per_macro=24)

# Instantiate the agent without tensorboard to avoid missing dependency errors
model = PPO("MlpPolicy", env, verbose=1)

print("Training model...")
# Train the agent
model.learn(total_timesteps=100000)

# Save the agent
model.save("ppo_kaggriculture_hrl")
print("Model saved.")

